# --- Hand-written: tenant isolation, grants and seed data ---------------------------------

TENANT_EXPR = "nullif(current_setting('app.tenant_id', true), '')::uuid"
BYPASS_EXPR = "current_setting('app.bypass_rls', true) = 'on'"

# table -> column holding the tenant id
RLS_TABLES = {
    "tenants": "id",
    "users": "tenant_id",
    "user_roles": "tenant_id",
    "auth_sessions": "tenant_id",
    "api_keys": "tenant_id",
    "audit_logs": "tenant_id",
}


def _app_role() -> str:
    from app.core.config import get_settings

    role = get_settings().db_app_role
    if not role.replace("_", "").isalnum():
        raise ValueError("invalid DB_APP_ROLE")
    return role


def _enable_rls() -> None:
    for table, col in RLS_TABLES.items():
        op.execute(f"ALTER TABLE {table} ENABLE ROW LEVEL SECURITY")
        # FORCE so even the table owner is subject to RLS outside migrations' superuser paths.
        op.execute(f"ALTER TABLE {table} FORCE ROW LEVEL SECURITY")
        op.execute(
            f"CREATE POLICY tenant_isolation ON {table} "
            f"USING ({col} = {TENANT_EXPR} OR {BYPASS_EXPR}) "
            f"WITH CHECK ({col} = {TENANT_EXPR} OR {BYPASS_EXPR})"
        )


def _grant_app_role() -> None:
    role = _app_role()
    op.execute(f"GRANT USAGE ON SCHEMA public TO {role}")
    op.execute(f"GRANT SELECT ON permissions, roles, role_permissions TO {role}")
    op.execute(
        f"GRANT SELECT, INSERT, UPDATE, DELETE ON tenants, users, user_roles, auth_sessions, "
        f"api_keys TO {role}"
    )
    # Audit log is append-only for the application.
    op.execute(f"GRANT SELECT, INSERT ON audit_logs TO {role}")


