def _seed_permissions_and_roles() -> None:
    import uuid as _uuid

    ns = _uuid.UUID("6f1d8a52-6a8e-4c8a-9a52-4f6f0d4b9c11")
    perms = sa.table(
        "permissions", sa.column("key", sa.String), sa.column("description", sa.String)
    )
    roles = sa.table(
        "roles",
        sa.column("id", sa.Uuid),
        sa.column("key", sa.String),
        sa.column("name", sa.String),
        sa.column("description", sa.String),
        sa.column("is_system", sa.Boolean),
    )
    role_perms = sa.table(
        "role_permissions", sa.column("role_id", sa.Uuid), sa.column("permission_key", sa.String)
    )
    op.bulk_insert(perms, [{"key": str(k), "description": v} for k, v in SEED_PERMISSIONS.items()])
    role_rows, rp_rows = [], []
    for key, spec in SEED_ROLES.items():
        rid = _uuid.uuid5(ns, key)
        role_rows.append(
            {
                "id": rid,
                "key": key,
                "name": spec["name"],
                "description": spec["description"],
                "is_system": True,
            }
        )
        rp_rows += [{"role_id": rid, "permission_key": str(p)} for p in spec["permissions"]]
    op.bulk_insert(roles, role_rows)
    op.bulk_insert(role_perms, rp_rows)


